class Solution:
    def maxArrayValue(self, nums: List[int]) -> int:
        cur = nums[-1]
        best = 0
        for i in range(len(nums) - 2, -1, -1):
            if nums[i] <= cur:
                cur += nums[i]
            else:
                best = max(best, cur)
                cur = nums[i]
        return max(best, cur)
