import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    kind = draw(st.integers(0, 4))
    if kind == 0:
        # all equal
        v = draw(st.integers(1, 10))
        nums = [v] * n
    elif kind == 1:
        # sorted increasing
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)))
    elif kind == 2:
        # strictly decreasing where possible
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
    elif kind == 3:
        # extremes of the (scaled-down) range
        nums = draw(st.lists(st.sampled_from([1, 10]), min_size=n, max_size=n))
    else:
        nums = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        nums = json.loads(inp)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    for x in nums:
        if not isinstance(x, int) or isinstance(x, bool):
            return False
        if not (1 <= x <= 10**6):
            return False
    return True

def ref(inp):
    nums = tuple(json.loads(inp))
    # Exhaustive search over every reachable array state; the answer is the
    # maximum element over all states (we may stop after any number of operations).
    seen = set()
    best = 0
    stack = [nums]
    seen.add(nums)
    while stack:
        cur = stack.pop()
        best = max(best, max(cur))
        for i in range(len(cur) - 1):
            if cur[i] <= cur[i + 1]:
                nxt = cur[:i] + (cur[i] + cur[i + 1],) + cur[i + 2:]
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
    return json.dumps(best)
